func TestParseSpacefastDeliverSink(t *testing.T) {
	for _, ok := range []string{"spacefast:my-page", "spacefast:xmas-flights,public", "spacefast:a1"} {
		if _, err := ParseDeliverSink(ok); err != nil {
			t.Errorf("ParseDeliverSink(%q) = %v, want ok", ok, err)
		}
	}
	for _, bad := range []string{"spacefast:", "spacefast:Bad_Name", "spacefast:x", "spacefast:ok-name,shiny", "spacefast:-lead"} {
		if _, err := ParseDeliverSink(bad); err == nil {
			t.Errorf("ParseDeliverSink(%q) succeeded, want error", bad)
		}
	}
}

func TestRenderSpacefastPageEscapesAndTabulates(t *testing.T) {
	body := []byte(`{"results":[{"name":"<script>x</script>","price":129,"link":"https://example.com/a"},{"name":"b","price":99.5}]}`)
	page := string(renderSpacefastPage("demo-page", body))
	for _, want := range []string{"<table>", "<th>name</th>", "<th>price</th>", "&lt;script&gt;", "99.5", `<a href="https://example.com/a">`, "2 rows"} {
		if !strings.Contains(page, want) {
			t.Errorf("rendered page missing %q", want)
		}
	}
	if strings.Contains(page, "<script>x") {
		t.Error("rendered page contains unescaped output")
	}
	if !strings.Contains(page, "<th>name</th><th>price</th><th>link</th>") {
		t.Error("table columns should keep the output's field order")
	}
	enveloped := string(renderSpacefastPage("demo-page", []byte(`{"meta":{"source":"live"},"results":[{"title":"a","source":"x"}]}`)))
	if !strings.Contains(enveloped, "<th>title</th><th>source</th>") {
		t.Error("envelope keys should not reorder row columns")
	}
	nested := string(renderSpacefastPage("demo-page", []byte(`[{"zeta":{"inner":1},"alpha":2}]`)))
	if !strings.Contains(nested, "<th>zeta</th><th>alpha</th>") {
		t.Error("nested objects should not disturb top-level column order")
	}
	nestedRows := string(renderSpacefastPage("demo-page", []byte(`[{"children":[{"b":1,"a":2}],"a":3,"b":4}]`)))
	if !strings.Contains(nestedRows, "<th>children</th><th>a</th><th>b</th>") {
		t.Error("records nested inside a row should not reorder the table's columns")
	}
}

func TestSpacefastKeepsLargeNumbersExact(t *testing.T) {
	body := []byte(`[{"id":9007199254740993,"ratio":0.1}]`)
	if page := string(renderSpacefastPage("demo-page", body)); !strings.Contains(page, "<td>9007199254740993</td>") {
		t.Error("table should show integers above 2^53 exactly")
	}
	if data := string(spacefastDataFile(body)); !strings.Contains(data, "9007199254740993") || !strings.Contains(data, "0.1") {
		t.Errorf("data.json should keep numbers exact, got %s", data)
	}
}

func TestSpacefastTruncateKeepsUTF8(t *testing.T) {
	long := strings.Repeat("é", 400)
	got := spacefastTruncate(long, 300)
	if !utf8.ValidString(got) || utf8.RuneCountInString(got) != 301 {
		t.Errorf("truncation should keep 300 whole characters plus an ellipsis, got %d runes", utf8.RuneCountInString(got))
	}
	if spacefastTruncate("short", 300) != "short" {
		t.Error("short text should be unchanged")
	}
	plain := string(renderSpacefastPage("demo-page", []byte("NAME  PRICE\n<b>  1\n")))
	if !strings.Contains(plain, "<pre>") || !strings.Contains(plain, "&lt;b&gt;") {
		t.Error("non-JSON output should render escaped inside <pre>")
	}
}

