func TestSpacefastRefusesPlaintextCredentials(t *testing.T) {
	refused := []string{"http://example.com", "http://10.0.0.5:8080", "http://[::ffff:8.8.8.8]"}
	for _, raw := range refused {
		u, _ := url.Parse(raw)
		if spacefastPlaintextCredentialError(u) == nil {
			t.Errorf("%s: credentials over plaintext http should be refused", raw)
		}
	}
	allowed := []string{"https://api.spacefast.com", "http://localhost:8080", "http://127.0.0.1:9000", "http://[::1]:9000", "http://LOCALHOST."}
	for _, raw := range allowed {
		u, _ := url.Parse(raw)
		if err := spacefastPlaintextCredentialError(u); err != nil {
			t.Errorf("%s: should be allowed, got %v", raw, err)
		}
	}
	if _, err := spacefastPublish("http://example.com", "secret-token", map[string]any{}, nil); err == nil || !strings.Contains(err.Error(), "plaintext") {
		t.Errorf("spacefastPublish to non-loopback http with a token = %v, want plaintext refusal", err)
	}
}

// captureStderr runs fn with os.Stderr redirected and returns what it wrote.
// written reports, while fn runs, how many bytes have reached stderr so far.
func captureStderr(t *testing.T, fn func(written func() int) error) (string, error) {
	t.Helper()
	r, w, err := os.Pipe()
	if err != nil {
		t.Fatal(err)
	}
	prev := os.Stderr
	os.Stderr = w
	var mu sync.Mutex
	var buf bytes.Buffer
	done := make(chan struct{})
	go func() {
		defer close(done)
		chunk := make([]byte, 4096)
		for {
			n, rerr := r.Read(chunk)
			mu.Lock()
			buf.Write(chunk[:n])
			mu.Unlock()
			if rerr != nil {
				return
			}
		}
	}()
	written := func() int {
		mu.Lock()
		defer mu.Unlock()
		return buf.Len()
	}
	ferr := fn(written)
	os.Stderr = prev
	_ = w.Close()
	<-done
	_ = r.Close()
	return buf.String(), ferr
}

// TestDeliverSpacefastAnonymousKeepsPageKeyOutOfOutput (Codex r1 class B,
// contract 1): the page key a publish mints is held the moment its receipt is
// decoded, before anything prints and before any return, and an anonymous
// page's key-bearing links go only to its page record. Neither the first
// publish nor the update prints the key; both name the record. An account page
// still prints its live URL.
func TestDeliverSpacefastAnonymousKeepsPageKeyOutOfOutput(t *testing.T) {
	key := "sfc_" + "Q7m2Xv9LpR4tZZ"
	noSpaceID := false
	srv := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		_ = r.ParseMultipartForm(1 << 20)
		var payload map[string]any
		_ = json.Unmarshal([]byte(r.FormValue("payload")), &payload)
		rec := map[string]any{"space": map[string]any{"id": "spc_demo", "liveUrl": "https://demo-page.space.fast"}}
		if noSpaceID {
			rec["space"] = map[string]any{}
		}
		if _, update := payload["spaceId"]; !update && r.Header.Get("Authorization") == "" {
			rec["claim"] = map[string]any{"key": key, "url": "https://demo-page.space.fast/__/" + key, "claimUrl": "https://spacefast.com/claim#" + key}
		}
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusCreated)
		_ = json.NewEncoder(w).Encode(map[string]any{"data": rec})
	}))
	defer srv.Close()
	spacefastTestEnv(t, srv.URL)

	var written func() int
	var held []string
	heldLate := false
	prevHold := cliutil.Hold
	cliutil.Hold = func(source credkit.Source, values ...string) {
		if source != "minted:spacefast-page-key" {
			return
		}
		held = append(held, values...)
		if written != nil && written() > 0 {
			heldLate = true
		}
	}
	t.Cleanup(func() { cliutil.Hold = prevHold })
	deliver := func(target string) (string, error) {
		return captureStderr(t, func(w func() int) error {
			written = w
			defer func() { written = nil }()
			return Deliver(DeliverSink{Scheme: "spacefast", Target: target}, []byte(`[{"id":1}]`), false)
		})
	}

	dir, name, err := spacefastDeliveryPath(spacefastScope(srv.URL, "", "") + "|demo-page")
	if err != nil {
		t.Fatal(err)
	}
	record := filepath.Join(dir, name)
	for i, verb := range []string{"Published", "Updated"} {
		out, err := deliver("demo-page")
		if err != nil {
			t.Fatalf("%s: %v", verb, err)
		}
		if strings.Contains(out, key) {
			t.Errorf("%s printed the page key:\n%s", verb, out)
		}
		if !strings.Contains(out, verb+" on Spacefast as a private page") || !strings.Contains(out, record) || !strings.Contains(out, "SPACEFAST_TOKEN") {
			t.Errorf("%s does not say the page is private and its links are in %s:\n%s", verb, record, out)
		}
		if i == 0 && !slices.Contains(held, key) {
			t.Errorf("the minted page key was not held as minted:spacefast-page-key: %q", held)
		}
	}
	if heldLate {
		t.Error("the page key was held after output had started")
	}
	data, err := os.ReadFile(record)
	if err != nil || !bytes.Contains(data, []byte(key)) {
		t.Errorf("the page record does not keep the key (err %v):\n%s", err, data)
	}

	// A receipt that is refused (no space id) still has its key held first.
	held, noSpaceID = nil, true
	if _, err := deliver("other-page"); err == nil {
		t.Error("a receipt with no space id should be refused")
	}
	if !slices.Contains(held, key) {
		t.Errorf("a refused receipt's page key was not held before the refusal: %q", held)
	}

	// An account page prints its live URL as before.
	noSpaceID = false
	t.Setenv("SPACEFAST_TOKEN", "sf_test_"+"token1234")
	out, err := deliver("account-page")
	if err != nil {
		t.Fatal(err)
	}
	if !strings.Contains(out, "Published on Spacefast: https://demo-page.space.fast") {
		t.Errorf("an account page should print its live URL:\n%s", out)
	}
}
